package dustin.cex.domains.travelrule;

import static org.junit.jupiter.api.Assertions.*;
import com.sun.net.httpserver.*;
import java.net.*;
import java.nio.charset.StandardCharsets;
import java.math.BigDecimal;
import java.security.*;
import java.time.*;
import java.util.*;
import java.util.concurrent.*;
import java.util.concurrent.atomic.*;
import org.junit.jupiter.api.*;
import org.springframework.transaction.support.TransactionSynchronizationManager;
import tools.jackson.databind.*;
import tools.jackson.databind.node.*;
import tools.jackson.databind.json.JsonMapper;

/** 소유 HTTP 대역의 서명/본문·키·복호화 결합 계약을 검사한다. 공식 모듈의 인증 암호 수학을 구현/검증한 시험은 아니다. */
class CodeVaspTransferDataClientTest {
    static final JsonMapper JSON=JsonMapper.builder().build();
    static final String NAME="가상 수취인",SENDER="가상 송금인",ADDRESS="bcrt1q"+"a".repeat(38),TX="b".repeat(64);
    final UUID id=UUID.randomUUID();
    final String outgoing=Base64.getEncoder().encodeToString(new byte[64]),incoming=Base64.getEncoder().encodeToString("x".repeat(64).getBytes(StandardCharsets.US_ASCII));
    HttpServer module,gateway;ExecutorService workers;CodeVaspTransport transport;CodeVaspTransferDataClient client;KeyPair pair;String ownKey,peerKey;
    volatile String mode="NORMAL";AtomicLong nonce=new AtomicLong(1);AtomicInteger signs=new AtomicInteger(),sent=new AtomicInteger(),decrypts=new AtomicInteger();
    AtomicReference<Throwable> callbackFailure=new AtomicReference<>();CountDownLatch release=new CountDownLatch(1);AtomicReference<String> signedBody=new AtomicReference<>();
    CodeVaspDirectoryClient.Key key(){return new CodeVaspDirectoryClient.Key(peerKey,Instant.now().plusSeconds(3600));}
    CodeVaspDirectoryClient.Vasp peer(CodeVaspDirectoryClient.Key key){return new CodeVaspDirectoryClient.Vasp("counterparty","가상 송신 거래소","가상 송신 사업자","KR","CODE",true,List.of(key));}
    CodeVaspTransferDataClient.Request request(){var key=key();return new CodeVaspTransferDataClient.Request(new CodeVaspTransactionClient.Request(id,TX,ADDRESS),new BigDecimal("0.25000000"),NAME,peer(key),key);}
    CodeVaspCounterpartyPolicy approved(){return new CodeVaspCounterpartyPolicy(JSON.writeValueAsString(List.of(Map.of("entityId","counterparty","legalName","가상 송신 사업자","reviewReference","LOCAL-TEST-ONLY","evidenceSha256","a".repeat(64),"validFrom",Instant.now().minusSeconds(60).toString(),"validUntil",Instant.now().plusSeconds(60).toString()))));}
    @BeforeEach void start()throws Exception{
        pair=KeyPairGenerator.getInstance("Ed25519").generateKeyPair();ownKey=Base64.getEncoder().encodeToString(Arrays.copyOfRange(pair.getPublic().getEncoded(),12,44));peerKey=Base64.getEncoder().encodeToString(new byte[32]);
        workers=Executors.newVirtualThreadPerTaskExecutor();module=HttpServer.create(new InetSocketAddress("127.0.0.1",0),0);gateway=HttpServer.create(new InetSocketAddress("127.0.0.1",0),0);module.setExecutor(workers);gateway.setExecutor(workers);
        module.createContext("/api/v1/code/api-payloads",e->{try{
            signs.incrementAndGet();assertEquals("POST",e.getRequestMethod());var command=JSON.readTree(e.getRequestBody().readAllBytes());assertEquals("CODE",command.path("allianceName").asString());assertEquals("VERIFICATION_TRANSACTION_ID",command.path("apiType").asString());assertEquals(peerKey,command.path("remotePublicKey").asString());var r=command.path("request");assertEquals(6,r.size());assertEquals(id.toString(),r.path("transferId").asString());assertEquals(TX,r.path("txid").asString());assertEquals(ADDRESS,r.path("beneficiaryAddress").asString());assertEquals(ADDRESS,r.path("beneficiaryWalletAddress").asString());assertEquals("LEGL",r.path("beneficiaryNameIdentifierType").asString());assertEquals(NAME,r.path("beneficiaryNaturalPersonLastName").asString());
            if(mode.equals("SIGN_SLOW")){slow(e);return;}
            var body=JSON.createObjectNode().put("transferId",id.toString()).put("txid",TX).put("beneficiaryAddress",ADDRESS).put("payload",outgoing);
            switch(mode){case "WRONG_ID"->body.put("transferId",UUID.randomUUID().toString());case "WRONG_TX"->body.put("txid","c".repeat(64));case "WRONG_ADDRESS"->body.put("beneficiaryAddress","bcrt1q"+"c".repeat(38));case "PLAIN_PII"->body.put("beneficiaryName",NAME);case "PLAIN_PAYLOAD"->body.put("payload",NAME);case "SHORT_PAYLOAD"->body.put("payload","YWJj");case "MISSING_PAYLOAD"->body.remove("payload");}
            String raw=JSON.writeValueAsString(body).replace(",",", ");if(mode.equals("DUPLICATE_SIGNED_FIELD"))raw=raw.substring(0,raw.length()-1)+",\"transferId\":\""+id+"\"}";if(mode.equals("TRAILING_SIGNED_OBJECT"))raw+=" {}";signedBody.set(raw);String date=Instant.now().toString();long number=nonce.incrementAndGet();var sig=Signature.getInstance("Ed25519");sig.initSign(pair.getPrivate());sig.update((date+raw+number).getBytes(StandardCharsets.UTF_8));send(e,200,JSON.writeValueAsString(JSON.createObjectNode().put("signature",Base64.getEncoder().encodeToString(sig.sign())).put("nonce",number).put("dateTime",date).put("publicKey",ownKey).put("body",raw)));
        }catch(Throwable t){callbackFailure.compareAndSet(null,t);send(e,500,"격리 서명 대역 실패");}});
        gateway.createContext("/v1/code/verification/tx/counterparty",e->{try{
            sent.incrementAndGet();assertEquals("PUT",e.getRequestMethod());String raw=new String(e.getRequestBody().readAllBytes(),StandardCharsets.UTF_8);assertEquals(signedBody.get(),raw);assertFalse(raw.contains(NAME));assertFalse(raw.contains(SENDER));assertFalse(raw.contains("1990-01-01"));assertEquals(peerKey,e.getRequestHeaders().getFirst("X-Code-Req-Remote-PubKey"));assertEquals(ownKey,e.getRequestHeaders().getFirst("X-Code-Req-PubKey"));assertEquals("code:cex-data",e.getRequestHeaders().getFirst("X-Request-Origin"));var sig=Signature.getInstance("Ed25519");sig.initVerify(pair.getPublic());sig.update((e.getRequestHeaders().getFirst("X-Code-Req-Datetime")+raw+e.getRequestHeaders().getFirst("X-Code-Req-Nonce")).getBytes(StandardCharsets.UTF_8));assertTrue(sig.verify(Base64.getDecoder().decode(e.getRequestHeaders().getFirst("X-Code-Req-Signature"))));
            if(mode.equals("GATEWAY_SLOW")){slow(e);return;}if(mode.equals("GATEWAY_ERROR")){send(e,503,"개인정보가 섞인 공급사 원문");return;}if(mode.equals("REDIRECT")){e.getResponseHeaders().set("Location",moduleBase()+"/api/v1/code/decrypt");send(e,302,"리다이렉트 원문");return;}
            var result=JSON.createObjectNode().put("result","normal").put("transferId",id.toString()).put("currency","btc").put("amount","0.250000000").put("payload",incoming);
            switch(mode){case "RESPONSE_ID"->result.put("transferId",UUID.randomUUID().toString());case "CURRENCY"->result.put("currency","ETH");case "AMOUNT"->result.put("amount","0.26");case "INEXACT_AMOUNT"->result.put("amount","0.250000001");case "AMOUNT_NUMBER"->result.put("amount",0.25);case "EXPONENT_AMOUNT"->result.put("amount","2.5e-1");case "EXTRA_PII"->result.put("fullName",NAME);case "BAD_CIPHERTEXT"->result.put("payload","invalid");case "UNKNOWN_RESULT"->result.put("result","approved");}
            if(mode.startsWith("ERROR_"))result=JSON.createObjectNode().put("result","error").put("transferId",id.toString()).put("reasonType",mode.substring(6)).put("reasonMsg","개인정보가 섞인 상세 원문");
            send(e,200,JSON.writeValueAsString(result));
        }catch(Throwable t){callbackFailure.compareAndSet(null,t);send(e,500,"격리 게이트웨이 대역 실패");}});
        module.createContext("/api/v1/code/decrypt",e->{try{
            decrypts.incrementAndGet();assertEquals("POST",e.getRequestMethod());var request=JSON.readTree(e.getRequestBody().readAllBytes());assertEquals("CODE",request.path("allianceName").asString());assertEquals(peerKey,request.path("remotePublicKey").asString());assertEquals(incoming,request.path("data").asString());if(mode.equals("DECRYPT_SLOW")){slow(e);return;}if(mode.equals("DECRYPT_ERROR")){send(e,400,"복호화 실패 원문");return;}
            var body=identity();String text=JSON.writeValueAsString(body);if(mode.equals("BODY_MISMATCH"))text="{}";if(mode.equals("BODY_TRAILING"))text+=" {}";var response=JSON.createObjectNode().set("body",body);((ObjectNode)response).put("bodyString",text);send(e,200,JSON.writeValueAsString(response));
        }catch(Throwable t){callbackFailure.compareAndSet(null,t);send(e,500,"격리 복호화 대역 실패");}});
        module.start();gateway.start();transport=new CodeVaspTransport(new CodeVaspSettings(gatewayBase(),moduleBase(),"cex-data",ownKey));client=new CodeVaspTransferDataClient(transport,approved());
    }
    ObjectNode identity(){
        var root=JSON.createObjectNode();var ivms=root.putObject("ivms101");var origin=ivms.putObject("Originator");var people=origin.putArray("originatorPersons");var sender=people.addObject().putObject("naturalPerson");sender.putObject("name").putArray("nameIdentifier").addObject().put("nameIdentifierType",mode.equals("LOWERCASE_LEGL")?"legl":"LEGL").put("primaryIdentifier",SENDER);sender.putObject("dateAndPlaceOfBirth").put("dateOfBirth","1990-01-01");origin.putArray("accountNumber").add("bc1q"+"d".repeat(38));
        var receiver=ivms.putObject("Beneficiary");var receiverPerson=receiver.putArray("beneficiaryPersons").addObject().putObject("naturalPerson");receiverPerson.putObject("name").putArray("nameIdentifier").addObject().put("nameIdentifierType","LEGL").put("primaryIdentifier",mode.equals("DIFFERENT_RECIPIENT_NAME")?"다른 수취인":NAME);var accounts=receiver.putArray("accountNumber");accounts.add(mode.equals("RECEIVER_ACCOUNT")?"bcrt1q"+"e".repeat(38):ADDRESS);ivms.putObject("OriginatingVASP");
        switch(mode){case "MISSING_DOB"->sender.remove("dateAndPlaceOfBirth");case "BAD_DOB"->((ObjectNode)sender.path("dateAndPlaceOfBirth")).put("dateOfBirth","1990-02-30");case "FUTURE_DOB"->((ObjectNode)sender.path("dateAndPlaceOfBirth")).put("dateOfBirth","2100-01-01");case "MULTIPLE_PEOPLE"->people.add(people.get(0).deepCopy());case "LEGAL_PERSON"->((ObjectNode)people.get(0)).putObject("legalPerson");case "MISSING_ORIGINATING_VASP"->ivms.remove("OriginatingVASP");case "DUPLICATE_ACCOUNT"->accounts.add(ADDRESS);case "MISSING_NAME"->sender.remove("name");}
        return root;
    }
    String moduleBase(){return "http://127.0.0.1:"+module.getAddress().getPort();}String gatewayBase(){return "http://127.0.0.1:"+gateway.getAddress().getPort();}
    void send(HttpExchange e,int status,String text)throws java.io.IOException{byte[] bytes=text.getBytes(StandardCharsets.UTF_8);try(e){e.sendResponseHeaders(status,bytes.length);e.getResponseBody().write(bytes);}}
    void slow(HttpExchange e)throws Exception{try(e){e.sendResponseHeaders(200,0);e.getResponseBody().write('{');e.getResponseBody().flush();assertTrue(release.await(10,TimeUnit.SECONDS));}catch(java.io.IOException closed){}}
    @AfterEach void close(){release.countDown();if(transport!=null)transport.close();if(module!=null)module.stop(0);if(gateway!=null)gateway.stop(0);if(workers!=null)workers.close();assertNull(callbackFailure.get());}
    CodeVaspSubmissionFailure failure(CodeVaspSubmissionFailure.Admission admission){var e=assertThrows(CodeVaspSubmissionFailure.class,()->client.exchange(request()));assertEquals(admission,e.admission());assertNull(e.getCause());assertFalse(e.toString().contains(NAME));assertFalse(e.toString().contains("원문"));return e;}
    @Test void signedEncryptedRequestAndBoundPrivateReplyUseFixedContract(){var result=client.exchange(request());assertEquals("NORMAL",result.status());assertEquals(id,result.data().transferId());assertEquals(new BigDecimal("0.25000000"),result.data().amount());assertEquals(SENDER,result.data().originator().primaryName());assertEquals(LocalDate.of(1990,1,1),result.data().originator().dateOfBirth());assertEquals(NAME,result.data().beneficiary().primaryName());assertEquals(64,result.data().ciphertextHash().length());assertEquals(1,signs.get());assertEquals(1,sent.get());assertEquals(1,decrypts.get());}
    @Test void cipherCannotChangePublicBindingOrLeakPlainPersonalFields(){for(String bad:List.of("WRONG_ID","WRONG_TX","WRONG_ADDRESS","PLAIN_PII","PLAIN_PAYLOAD","SHORT_PAYLOAD","MISSING_PAYLOAD","DUPLICATE_SIGNED_FIELD","TRAILING_SIGNED_OBJECT")){mode=bad;failure(CodeVaspSubmissionFailure.Admission.NOT_SENT);}assertEquals(0,sent.get());assertEquals(0,decrypts.get());}
    @Test void publicReplyMustMatchBeforeDecryption(){for(String bad:List.of("RESPONSE_ID","CURRENCY","AMOUNT","INEXACT_AMOUNT","AMOUNT_NUMBER","EXPONENT_AMOUNT","EXTRA_PII","UNKNOWN_RESULT")){mode=bad;failure(CodeVaspSubmissionFailure.Admission.OUTCOME_UNKNOWN);}assertEquals(0,decrypts.get());}
    @Test void documentedErrorReasonsKeepNoRawMessageOrDecryptedData(){for(String reason:List.of("NOT_FOUND_TXID","LACK_OF_INFORMATION","UNKNOWN","UNKNOWN_TRANSFER_ID")){mode="ERROR_"+reason;var result=client.exchange(request());assertEquals("ERROR",result.status());assertEquals(reason,result.reason());assertNull(result.data());assertFalse(result.toString().contains("원문"));}assertEquals(0,decrypts.get());}
    @Test void unknownErrorAndMalformedCiphertextAreUnusable(){mode="ERROR_NEW_REASON";failure(CodeVaspSubmissionFailure.Admission.OUTCOME_UNKNOWN);mode="BAD_CIPHERTEXT";failure(CodeVaspSubmissionFailure.Admission.OUTCOME_UNKNOWN);assertEquals(0,decrypts.get());}
    @Test void decryptedObjectAndOriginalStringMustAgree(){for(String bad:List.of("BODY_MISMATCH","BODY_TRAILING","DECRYPT_ERROR")){mode=bad;failure(CodeVaspSubmissionFailure.Admission.OUTCOME_UNKNOWN);}}
    @Test void requiredNaturalPersonFieldsAndRecipientAccountCannotBeGuessed(){for(String bad:List.of("MISSING_DOB","BAD_DOB","FUTURE_DOB","MULTIPLE_PEOPLE","LEGAL_PERSON","MISSING_ORIGINATING_VASP","DUPLICATE_ACCOUNT","MISSING_NAME","RECEIVER_ACCOUNT")){mode=bad;failure(CodeVaspSubmissionFailure.Admission.OUTCOME_UNKNOWN);}}
    @Test void parsedNamesAreFactsAndDoNotPerformCurrentKycApproval(){mode="DIFFERENT_RECIPIENT_NAME";var result=client.exchange(request());assertEquals("다른 수취인",result.data().beneficiary().primaryName());assertEquals("NORMAL",result.status());mode="LOWERCASE_LEGL";assertEquals(SENDER,client.exchange(request()).data().originator().primaryName());}
    @Test void sensitiveDtosDoNotEchoNamesBirthOrAccounts(){var input=request();var result=client.exchange(input);for(String hidden:List.of(NAME,SENDER,"1990-01-01",ADDRESS)){for(String text:List.of(input.toString(),result.toString(),result.data().toString(),result.data().originator().toString(),result.data().beneficiary().toString()))assertFalse(text.contains(hidden));}}
    @Test void unsupportedPeerOrKeyNeverStartsIo(){var k=key();var p=peer(k);for(var wrong:List.of(new CodeVaspDirectoryClient.Vasp(p.entityId(),p.name(),p.legalName(),"US","CODE",true,List.of(k)),new CodeVaspDirectoryClient.Vasp(p.entityId(),p.name(),p.legalName(),"KR","GTR",true,List.of(k)),new CodeVaspDirectoryClient.Vasp(p.entityId(),p.name(),p.legalName(),"KR","CODE",false,List.of(k))))assertThrows(IllegalArgumentException.class,()->new CodeVaspTransferDataClient.Request(request().query(),BigDecimal.ONE,NAME,wrong,k));var expired=new CodeVaspDirectoryClient.Key(peerKey,Instant.now().minusSeconds(1));assertThrows(IllegalArgumentException.class,()->new CodeVaspTransferDataClient.Request(request().query(),BigDecimal.ONE,NAME,peer(expired),expired));assertEquals(0,signs.get());}
    @Test void invalidIdentityOrSubSatoshiExpectationNeverStartsIo(){var k=key();for(String name:List.of(""," ","이름\r\n"))assertThrows(IllegalArgumentException.class,()->new CodeVaspTransferDataClient.Request(request().query(),BigDecimal.ONE,name,peer(k),k));assertThrows(IllegalArgumentException.class,()->new CodeVaspTransferDataClient.Request(request().query(),new BigDecimal("0.000000001"),NAME,peer(k),k));assertEquals(0,signs.get());}
    @Test void databaseTransactionCannotDisclosePrivateIdentity(){TransactionSynchronizationManager.setActualTransactionActive(true);try{assertThrows(IllegalStateException.class,()->client.exchange(request()));}finally{TransactionSynchronizationManager.clear();}assertEquals(0,signs.get());}
    @Test void signingBodyDeadlineIsKnownNotSent(){mode="SIGN_SLOW";long start=System.nanoTime();failure(CodeVaspSubmissionFailure.Admission.NOT_SENT);assertTrue(Duration.ofNanos(System.nanoTime()-start).toSeconds()>=4);assertEquals(0,sent.get());}
    @Test void gatewayBodyDeadlineIsUnknownAndDoesNotDecrypt(){mode="GATEWAY_SLOW";long start=System.nanoTime();failure(CodeVaspSubmissionFailure.Admission.OUTCOME_UNKNOWN);assertTrue(Duration.ofNanos(System.nanoTime()-start).toSeconds()>=4);assertEquals(1,sent.get());assertEquals(0,decrypts.get());}
    @Test void decryptBodyDeadlineIsUnknownAfterOneGatewayRequest(){mode="DECRYPT_SLOW";long start=System.nanoTime();failure(CodeVaspSubmissionFailure.Admission.OUTCOME_UNKNOWN);assertTrue(Duration.ofNanos(System.nanoTime()-start).toSeconds()>=4);assertEquals(1,sent.get());assertEquals(1,decrypts.get());}
    @Test void gatewayFailureAndRedirectAreNotRetriedOrFollowed(){for(String bad:List.of("GATEWAY_ERROR","REDIRECT")){mode=bad;failure(CodeVaspSubmissionFailure.Admission.OUTCOME_UNKNOWN);}assertEquals(2,sent.get());assertEquals(2,signs.get());assertEquals(0,decrypts.get());}
    @Test void technicallyReachableButUnapprovedPeerCannotDiscloseIdentity(){client=new CodeVaspTransferDataClient(transport,new CodeVaspCounterpartyPolicy("[]"));failure(CodeVaspSubmissionFailure.Admission.NOT_SENT);assertEquals(0,signs.get());assertEquals(0,sent.get());assertEquals(0,decrypts.get());}
    @Test void missingSettingsNeverSendPrivateData(){try(var disabled=new CodeVaspTransport(new CodeVaspSettings("","","",""))){var e=assertThrows(CodeVaspSubmissionFailure.class,()->new CodeVaspTransferDataClient(disabled,approved()).exchange(request()));assertEquals(CodeVaspSubmissionFailure.Admission.NOT_SENT,e.admission());}assertEquals(0,signs.get());}
}
